 /** Numbers in record text: at most 4 decimals ("0.8123" instead of "0.81234567891234"). */
 const textOf = (c: Cell) =>
   typeof c === "number" && !Number.isInteger(c) ? String(Number(c.toFixed(4))) : cellText(c);

 /** "rows 3–5" for a run of rows, otherwise "rows 3, 7, 9". */
