       id: `rec_${shortHash(o.key)}_${first.line}`,
       sourceId,
       text: g.text,
       fields: Object.fromEntries(table.header.map((h, j) => [h, mergedValue(g.rows, j)])),
       locator: o.sheet ? `${o.sheet}, ${rowRange(lines)}` : rowRange(lines),
       market: market || o.scope.market,
       ...(language ? { language } : {}),
     };
