+        <Field label="Human rationale for restore" help="Required, 1-2000 characters. This is a next-run override, not a requirement approval.">{(id) => <TextArea id={id} value={rationale} maxLength={2000} onChange={setRationale} disabled={busy} />}</Field>
+        {guard && <p className="text-xs text-muted">{guard}</p>}
+        <Button variant="primary" disabled={busy || !!guard || !rationale.trim() || rationale.trim().length > 2000} onClick={restore}>Restore on next run</Button>
+      </>}
+    </section>}
+    <div className="flex flex-wrap items-center gap-3 text-xs text-muted"><span>{busy ? "Reading / saving pending restore state..." : pending ? `Pending restore state v${pending.version}` : "Pending restore state unavailable"}</span><Button size="sm" disabled={busy} onClick={refresh}>Refresh pending restores</Button></div>
+    {error && <p role="alert" className="text-sm text-danger">{error}</p>}
+    {notice && <p role="status" className="text-sm text-brand">{notice}</p>}
+  </div>;
+}
+
+function SourceLocations({ report, original }: { report: FilterReport; original: ReturnType<typeof filterRows>[number]["original"] }) {
+  if (!original) return <p className="text-xs text-warn">Original item is missing from the saved input.</p>;
+  const object = original as unknown as Record<string, unknown>;
+  const source = report.originalInput.sources.find((item) => item.id === object.sourceId || item.id === object.id);
+  return <details><summary className="cursor-pointer text-brand">Original source / provenance</summary><Json value={source ?? { sourceId: object.sourceId, locator: object.locator, evidence: object.evidence, findingIds: object.findingIds, sourceIds: object.sourceIds }} /></details>;
+}
+
+function Json({ value }: { value: unknown }) {
+  const text = safeFilterJson(value);
+  return <pre className="mt-2 max-h-64 overflow-auto whitespace-pre-wrap break-words rounded bg-panel-2 p-2 text-xs">{text.slice(0, 50000)}{text.length > 50000 ? "\n[Display truncated at 50,000 characters; saved data is unchanged.]" : ""}</pre>;
+}

