import { useState } from "react";
import { Field } from "@/components/ui/Field";
import {
  TextInput,
  TextArea,
  NumberInput,
  Slider,
  Select,
  ChipSelect,
  Toggle,
  ListEditor,
} from "@/components/ui/controls";
import { Button } from "@/components/ui/Button";
import { dataflowStore } from "./store";
import { api, ReqflowError } from "@/lib/api";
import { useSettings } from "@/lib/settings";
import type { ParamSpec, WorkflowBlock, FileRef } from "@reqflow/core";

export function ParamField({ block, spec }: { block: WorkflowBlock; spec: ParamSpec }) {
  const [error, setError] = useState<string | null>(null);

import {
  connect,
  createBlock,
  traceLineage,
  type SplitterGroup,
  type SplitterReport,
} from "@reqflow/core";
import { fixtureRun } from "@reqflow/core/fixtures";
import { describe, expect, it } from "vitest";
import {
  chartWidth,
  filterSignals,
  formatScore,
  matrixDescription,
  rankedGroups,
  reportForStep,
  reportRevision,
  reportsInLineage,
  splitterBranches,
  splitterReviewGate,

import { z } from "zod";
import { Actor } from "./audit";
import { BlockKind } from "./blocks";
import { DataKey } from "./pipeline";
import { ProductScope } from "./scope";
import { SplitterReport } from "./splitter-report";
import { FilterReport } from "./filter-report";

/**
 * A block placed on a workplace. `id` is unique across the whole workflow, inner workplaces
 * included, so run status and outputs can be keyed by id alone.
 */
export interface WorkflowBlock {
  id: string;
  kind: BlockKind;
  label: string;
  position: { x: number; y: number };
  params: Record<string, unknown>; // validated per kind: parseBlockParams (blocks.ts)
  /** The block's own workplace. Present exactly when the kind has one (BLOCK_SPECS.hasInnerWorkplace). */
  inner?: WorkflowGraph;

import { z } from "zod";

/** Vehicle lines and markets named in the briefing. The schema stays open so other lines/markets work too. */
export const KNOWN_VEHICLE_LINES = ["1 Series", "5 Series", "7 Series"] as const;
export const KNOWN_MARKETS = ["EU", "CN", "US"] as const;

/** What a workflow run is about: one derivative in one market, looking `horizonYears` ahead. */
export const ProductScope = z.object({
  vehicleLine: z.string().min(1), // "1 Series"
  derivative: z.string().min(1).optional(), // "5-door", "Sedan", "Touring"
  vehicleCode: z.string().regex(/^[A-Z0-9]{1,6}$/), // short code used in requirement IDs, e.g. "F70"
  market: z.string().regex(/^[A-Z0-9]{2,6}$/), // "EU" | "CN" | "US" | …
  horizonYears: z.number().int().min(1).max(10), // briefing: think 3–5 years ahead
});
export type ProductScope = z.infer<typeof ProductScope>;

  list(): Promise<Workflow[]>;
  get(id: string): Promise<Workflow>;
  save(input: WorkflowSave): Promise<Workflow>;
  remove(id: string): Promise<void>;
};
files: {
  /** Opens the native file dialog and copies the chosen file into the data dir. null = cancelled. */
  import(): Promise<StoredFileInfo | null>;
};
runs: {
  start(workflowId: string): Promise<WorkflowRun>;
  get(runId: string): Promise<WorkflowRun>;
  list(workflowId?: string): Promise<WorkflowRun[]>;
  /** What one block emitted, per output port id. */
  blockOutput(runId: string, blockId: string): Promise<Record<string, PipelineData>>;
  /** Human routing correction, before an editable HIL gate continues. */
  reviewSplitter(runId: string, blockId: string, review: SplitterReview): Promise<WorkflowRun>;
  /** Pending human restorations; historical outputs are never changed. */
  filterReviewState(runId: string, blockId: string): Promise<FilterReviewState>;
  reviewFilter(runId: string, blockId: string, review: FilterReview): Promise<FilterReviewState>;

import { z } from "zod";
import { RequirementCategory } from "./category";
import { EvidenceRef } from "./source";

/** Signal types the briefing asks us to extract. */
export const FindingKind = z.enum([
  "complaint", // recurring pain point
  "unmet_need", // something customers want but don't get
  "praise", // keep/protect — what customers love
  "competitor_advantage", // a competitor does it better
  "market_trend", // forward-looking signal (3–5 years)
  "usage_pattern", // from equipment take rates / sales volumes
]);
export type FindingKind = z.infer<typeof FindingKind>;

/** A normalized, evidence-linked signal. Every finding must cite at least one source. */
export const Finding = z.object({
  id: z.string().startsWith("fnd_"),
  kind: FindingKind,
  statement: z.string().min(1), // one normalized sentence, e.g. "Rear legroom is too tight for adults."

});
export type ConfidenceSignal = z.infer<typeof ConfidenceSignal>;

/**
 * The agents' confidence in a requirement as written (Add to Car). Separate from the evidence level
 * and the priority score: a must-have can still be low confidence, and that should catch the eye.
 */
export const RequirementConfidence = z.object({
  value: z.number().min(0).max(1),
  level: ConfidenceLevel,
  signals: z.array(ConfidenceSignal).min(1),
  method: z.string().min(1), // versioned, e.g. "agent-confidence@1"
});
export type RequirementConfidence = z.infer<typeof RequirementConfidence>;

export const Requirement = z.object({
  id: z.string().regex(REQUIREMENT_ID_PATTERN), // stable across versions
  version: z.number().int().positive(), // +1 on every content change
  title: z.string().min(1).max(120),
  description: z.string().min(1), // clear, actionable, customer-facing; no engineering specs

