 export function filterRows(report: FilterReport) {
   const originals = new Map(report.originalInput[report.primaryLayer].map((item) => [item.id, item]));
+  const records = new Map(report.originalInput.records.map((item) => [item.id, item]));
+  const sources = new Map(report.originalInput.sources.map((item) => [item.id, item]));
   return report.decisions.map((decision) => ({
     decision,
     original: originals.get(decision.itemId),
     search: `${safeFilterJson(decision)} ${safeFilterJson(originals.get(decision.itemId))} ${decision.quotes.map((quote) => {
-      const record = report.originalInput.records.find((item) => item.id === quote.recordId);
-      const source = report.originalInput.sources.find((item) => item.id === record?.sourceId);
+      const record = records.get(quote.recordId);
+      const source = sources.get(record?.sourceId ?? "");
       return `${record?.locator ?? ""} ${source?.title ?? ""} ${source?.uri ?? ""}`;
     }).join(" ")}`.toLowerCase(),
   }));
 }

+export interface FilterRestoreApi {
+  reviewFilter(runId: string, blockId: string, input: FilterReview): Promise<FilterReviewState>;
+  filterReviewState(runId: string, blockId: string): Promise<FilterReviewState>;
+}
+
+export async function saveFilterRestore(api: FilterRestoreApi, report: FilterReport, input: FilterReview, refreshed: (state: FilterReviewState | null) => void) {
+  try {
+    const saved = FilterReviewState.parse(await api.reviewFilter(report.runId, report.blockId, input));
+    if (saved.version <= input.expectedVersion) throw new Error("The backend did not confirm a new restore version.");
+    // Read pending state only. No historical run/report/output is fetched or mutated.
+    return FilterReviewState.parse(await api.filterReviewState(report.runId, report.blockId));
+  } catch (cause) {
+    try { refreshed(FilterReviewState.parse(await api.filterReviewState(report.runId, report.blockId))); }
+    catch (refreshError) {
+      refreshed(null);
+      throw new Error(`${cause instanceof Error ? cause.message : String(cause)} Pending-state refresh also failed: ${refreshError instanceof Error ? refreshError.message : String(refreshError)}. The save may have succeeded; refresh before retrying.`);
+    }
+    throw new Error(`${cause instanceof Error ? cause.message : String(cause)} Pending state was refreshed. Check the current version and explicitly retry if needed. Historical output is unchanged.`);
+  }
+}
+
 export function filterPage(rows: ReturnType<typeof filterRows>, tab: FilterTab, query: string, requestedPage: number) {
   const counts = { keep: 0, exclude: 0, review: 0 };
   for (const row of rows) counts[row.decision.outcome]++;
   const matching = rows.filter((row) => row.decision.outcome === tab && row.search.includes(query.trim().toLowerCase()));

