import {
  FilterReview,
  FilterReviewState,
  type FilterReport,
  type WorkflowRun,
} from "@reqflow/core";

export type FilterDecision = FilterReport["decisions"][number];
export const FILTER_TABS = [
  { value: "keep", label: "Kept" },
  { value: "exclude", label: "Excluded" },
  { value: "review", label: "Needs review" },
] as const;
